#include <errno.h>              /* Requires STDINC in filelist. */
#include <string.h>

#include <local/sys/types.h>
#include <local/sys/cpu.h>
#include <local/sys/err.h>
#include <local/sys/init.h>
#include <local/sys/lib.h>
#include <local/sys/umem.h>
#include <local/sys/xbuf.h>

#include "jxmn.h"
#include "json_parse.h"

#define ERR(err, out) if (err != ERR_OK) { goto out; }
#define ERR_MEM(var, err, out) if (var == NULL) { err = ERR_MEM; goto out; }

/*
 * The purpose and interface of this module is described in "json_parse.h".
 * Some implementation comments follow:
 *
 * The open-source JXMN parser is used to tokenize the raw JSON text into
 * a growable array of tokens, subject to a specifiable token limit.
 * JXMN handles the details of the syntax, but not the high-level structure.
 * JXMN is not exposed in the interface of this module, allowing this module
 * to potentially use a different JSON tokenizer/parser in future.
 */

/* JSON Value. */
struct tmm_json_value {
    enum tmm_json_type  type;       /* Type of JSON value (when parsed): */
    union {
        struct tmm_json_object *o;  /* Object ( key:value pairs). */
        struct tmm_json_array  *a;  /* Array of values. */
        struct tmm_json_string  s;  /* String (escaped). */
        INT64                   i;  /* Number (signed integer up to 64-bit). */
        BOOL                    b;  /* Boolean. */
                                    /* (Null type needs no storage). */
    } value;                        /* Value when parsed (depends on type). */
    BOOL                parsed :1;  /* Been parsed (needn't parse again). */
    BOOL                allocd :1;  /* Value in alloc'd memory (must free). */
    BOOL                edited :1;  /* Value has been edited or added. */
    UINT32              tokidx;     /* Token index (in JXMN token array). */
    struct tmm_json_cache *json;    /* JSON cache this is part of. */
    struct tmm_json_value  *owner;  /* JSON value that links to this (or NULL)
                                       (owner has type 'object' or 'array'). */
};

/* JSON key:value pair, a list of which comprises a JSON Object. */
struct json_keyval {
    struct tmm_json_string  key;            /* Key (name) when parsed. */
    UINT32              key_tokidx;     /* Key token index. */
    BOOL                key_parsed :1;  /* Key has been parsed. */
    BOOL                key_alloc  :1;  /* Key in alloc'd memory (must free). */
    struct tmm_json_value          *value;  /* Value. */
    TAILLIST_ENTRY(json_keyval) next;   /* Link in list. */
};

/* JSON Object (collection of key:value pairs). */
struct tmm_json_object {
    UINT32                          tokidx; /* Token index. */
    BOOL                            parsed; /* Has been parsed. */
    unsigned                        nkvps;  /* Number of key:value pairs. */
    TAILLIST_TAIL(, json_keyval)    kvps;   /* List of key:value pairs. */
    struct tmm_json_cache          *json;   /* JSON cache this is part of. */
    struct tmm_json_value          *parent; /* JSON value this is part of. */
};

/*
 * JSON Array (ordered list of values).
 * Create C array lazily with a fixed initial physical size. Grow on demand.
 * Does not shrink on demand- keeps largest size reached by the array.
 * 0 entries = 0 chunks, 1-20 entries = 1 chunk, 21-40 = 2 chunks, etc.
 * XXX: Not clear the C-array is a good representation of a JSON array.
 */
#define JSON_ARRAY_CHUNK_SIZE 20        /* How many values per allocd chunk */
struct tmm_json_array {
    UINT32                  tokidx;     /* Token index. */
    BOOL                    parsed;     /* Has been parsed. */
    unsigned                nvals;      /* Logical Size (number of values). */
    unsigned                nchunks;    /* Physical size (number of chunks). */
    struct tmm_json_value  *(*vals)[];  /* Ptr to Array of ptrs to values. */
    struct tmm_json_cache  *json;       /* JSON cache this is part of. */
    struct tmm_json_value  *parent;     /* JSON value this is part of. */
};

/* JSON Cache Instance. */
#define TOK_AVG_BYTES       32      /* Guesstimated average size of a token. */
#define TOK_GROW_INCR       512     /* Token array grows by this many tokens. */
struct tmm_json_cache {
    struct tmm_json_value  *root;       /* Root of parse tree, a JSON value. */
    struct xbuf             raw;        /* Raw unparsed script */
    UINT32                  tok_num;    /* Size of token array (num tokens). */
    UINT32                  tok_limit;  /* Max size token array can grow to. */
    jxmntok_t             (*tokens)[];  /* Ptr to growable array of tokens. */
    jxmn_parser             jxmn;       /* JXMN parser. */
    BOOL                    raw_valid;  /* Raw data valid (not rendered). */
    INT32                   ref;        /* Reference count. */
    /* XXX: Hash table of keys? That can be a later optimization. */
};

/* Shared Umem Caches for JSON Entities. */
static GLOBALSET    umem_handle_t tmm_json_value_cache = {0, };
static GLOBALSET    umem_handle_t tmm_json_keyval_cache = {0, };
static GLOBALSET    umem_handle_t tmm_json_object_cache = {0, };
static GLOBALSET    umem_handle_t tmm_json_array_cache = {0, };


/*******************************************************************************
* Internal Infrastructure and Helper Functions.
*/

static err_t tmm_json_cache_parse_value(struct tmm_json_value *val);
static err_t tmm_json_cache_parse_string(struct tmm_json_value *val);
static err_t tmm_json_keyval_create(struct json_keyval **kvp, const char* key,
                UINT32 len, struct tmm_json_value *val);

/*
 * Initialize infrastructure shared across instances.
 */
static err_t
tmm_json_cache_infra_init(void)
{
    err_t err = ERR_OK;

    if (!umem_cache_valid(tmm_json_value_cache)) {
        err = umem_cache_create(&tmm_json_value_cache, "JSON value",
                sizeof(struct tmm_json_value), sizeof(UINT64),
                NULL, NULL, NULL, NULL, UMC_OUTOFMEMLOG);
        ERR(err, out);
    }
    if (!umem_cache_valid(tmm_json_keyval_cache)) {
        err = umem_cache_create(&tmm_json_keyval_cache, "JSON keyval",
                sizeof(struct json_keyval), sizeof(UINT64),
                NULL, NULL, NULL, NULL, UMC_OUTOFMEMLOG);
        if (err != ERR_OK) {
            umem_cache_destroy(&tmm_json_value_cache);
            goto out;
        }
    }
    if (!umem_cache_valid(tmm_json_object_cache)) {
        err = umem_cache_create(&tmm_json_object_cache, "JSON object",
                sizeof(struct tmm_json_object), sizeof(UINT64),
                NULL, NULL, NULL, NULL, UMC_OUTOFMEMLOG);
        if (err != ERR_OK) {
            umem_cache_destroy(&tmm_json_value_cache);
            umem_cache_destroy(&tmm_json_keyval_cache);
            goto out;
        }
    }
    if (!umem_cache_valid(tmm_json_array_cache)) {
        err = umem_cache_create(&tmm_json_array_cache, "JSON array",
                sizeof(struct tmm_json_array), sizeof(UINT64),
                NULL, NULL, NULL, NULL, UMC_OUTOFMEMLOG);
        if (err != ERR_OK) {
            umem_cache_destroy(&tmm_json_value_cache);
            umem_cache_destroy(&tmm_json_keyval_cache);
            umem_cache_destroy(&tmm_json_object_cache);
            goto out;
        }
    }

out:
    return err;
}
INIT_FUNC(INIT_BASE, tmm_json_cache_infra_init);

/*
 * Uninitialize infrastructure shared across instances.
 */
static err_t
tmm_json_cache_infra_uninit(void)
{
    /* XXX: These crash if their caches have any blocks still checked out. */
    umem_cache_destroy(&tmm_json_value_cache);
    umem_cache_destroy(&tmm_json_keyval_cache);
    umem_cache_destroy(&tmm_json_object_cache);
    umem_cache_destroy(&tmm_json_array_cache);
    return ERR_OK;
}
INIT_FUNC(INIT_SHUTDOWN, tmm_json_cache_infra_uninit);

/*
 * Indicate whether a JSON Value is owned by another or by the cache.
 * If not, it is an unattached instance that can be safely destroyed
 * by an external caller of tmm_json_value_release().
 */
static inline BOOL
tmm_json_value_is_owned(struct tmm_json_value *val)
{
    return (val != NULL) && ((val->owner != NULL) ||
            ((val->json != NULL) && (val == val->json->root)));
}


/*
 * Set the edited flag up the owner chain of a tmm_json_value
 */
static inline void
tmm_json_value_set_edited(struct tmm_json_value *val)
{
    while (val != NULL) {
        val->edited = TRUE;
        val = val->owner;
    }
}

/*
 * Adds escape characters for tmm_json_string. Destination should already
 * be allocated to the appropriate size (strlen plus null terminator)
 * with the length set. Unicode escaping is not currently supported.
 */
static err_t
tmm_json_string_set_with_escapes(struct tmm_json_string *dest,
        struct tmm_json_string *src)
{
    err_t err = ERR_OK;
    int i = 0;
    int j = 0;
    int accounted = -1;

    if (src == NULL || dest == NULL) {
        err = ERR_VAL;
        goto out;
    }

    if (likely(dest->len == src->len)) {
        strncpy(dest->base, src->base, src->len);
        dest->base[dest->len] = '\0';
        goto out;
    }

    for (i = 0; i < src->len; i++) {
        switch(src->base[i]) {
            /* Simple cases, these chars cannot exist in json */
            case '\b':
                dest->base[j++] = '\\';
                dest->base[j++] = 'b';
                break;
            case '\f':
                dest->base[j++] = '\\';
                dest->base[j++] = 'f';
                break;
            case '\n':
                dest->base[j++] = '\\';
                dest->base[j++] = 'n';
                break;
            case '\r':
                dest->base[j++] = '\\';
                dest->base[j++] = 'r';
                break;
            case '\t':
                dest->base[j++] = '\\';
                dest->base[j++] = 't';
                break;

            /* Complex cases, where chars are included in escaped version */
            case '\"':
                if ((i == 0) || (accounted == i - 1) ||
                        (src->base[i - 1] != '\\')) {
                    dest->base[j++] = '\\';
                    dest->base[j++] = '\"';
                }
                break;
            case '\\':
                if (i + 1 < src->len) {
                    /* These cases are already escaped */
                    switch(src->base[i + 1]) {
                        case '\"':
                        case 'b':
                        case 'f':
                        case 'n':
                        case 'r':
                        case 't':
                        case '\\':
                            dest->base[j++] = src->base[i++];
                            dest->base[j++] = src->base[i];
                            accounted = i;
                        break;
                    }
                }
                /* Case where '\\' is not escaped or used as an escape */
                if (accounted != i) {
                    dest->base[j++] = '\\';
                    dest->base[j++] = '\\';
                    accounted = i;
                }
                break;
            default:
                dest->base[j++] = src->base[i];
        }
    }
    DBG_ASSERT("String length correct", dest->len == j);
    dest->base[j] = '\0';

out:
    return err;
}

/*
 * Counts the number of characters that will need to be escaped.
 */
static unsigned
tmm_json_string_count_unescaped(struct tmm_json_string *src)
{
    int i;
    unsigned count = 0;
    char prev = '\0';
    BOOL add_to_count = TRUE;
    int accounted = -1;

    if (src == NULL) {
        goto out;
    }

    for (i = 0; i < src->len; i++) {
        switch(src->base[i]) {
            case 'b':
            case 'f':
            case 'n':
            case 'r':
            case 't':
                /* Do not count the above chars */
                add_to_count = FALSE;
            case '\"':
            case '\\':
                /* Check if already escaped by previous char */
                if ((prev == '\\') && (accounted != (i - 1))) {
                    /* Previous char was escape, decrement count. */
                    count--;
                    prev = src->base[i];
                    add_to_count = TRUE;
                    accounted = i;
                    break;
                }
            case '\b':
            case '\f':
            case '\n':
            case '\r':
            case '\t':
                if (add_to_count) {
                    count++;
                } else {
                    /* Reset the flag */
                    add_to_count = TRUE;
                }
            default:
                prev = src->base[i];
        }
    }
out:
    return count;
}

/*
 * Allocate a new untyped, unowned JSON value. Return NULL if out of memory.
 */
static struct tmm_json_value *
tmm_json_value_alloc(void)
{
    struct tmm_json_value *val;

    val = umem_cache_alloc(tmm_json_value_cache, 0);
    if (val != NULL) {
        memset(val, 0, sizeof(struct tmm_json_value));
        val->type = JSON_TYPE_INVALID;
        val->owner = NULL;
    }
    return val;
}

/*
 * Free a JSON value that is disconnected from all other values.
 */
static void
tmm_json_value_free(struct tmm_json_value *val)
{
    DBG_ASSERT("not NULL", val != NULL);
    umem_cache_free(tmm_json_value_cache, val);
}

static void tmm_json_value_release(struct tmm_json_value *val);

/*
 * Allocate a new JSON key:value pair. Return NULL if out of memory.
 */
static struct json_keyval *
tmm_json_keyval_alloc(void)
{
    struct json_keyval *kv;

    kv = umem_cache_alloc(tmm_json_keyval_cache, 0);
    if (kv != NULL) {
        memset(kv, 0, sizeof(struct json_keyval));
    }
    return kv;
}

/*
 * Free a JSON keyval (must not be in a list).
 */
static void
tmm_json_keyval_free(struct json_keyval *kv)
{
    DBG_ASSERT("not NULL", kv != NULL);
    if (kv == NULL) {
        goto out;
    }
    if (kv->key_alloc) {
        ufree(kv->key.base);
    }
    if (kv->value != NULL) {
        tmm_json_value_release(kv->value);
    }
    umem_cache_free(tmm_json_keyval_cache, kv);
out:
    return;
}

/*
 * Allocate a new JSON object. Return NULL if out of memory.
 */
static struct tmm_json_object *
tmm_json_object_alloc(void)
{
    struct tmm_json_object *obj;

    obj = umem_cache_alloc(tmm_json_object_cache, 0);
    if (obj != NULL) {
        memset(obj, 0, sizeof(struct tmm_json_object));
    }
    return obj;
}

/*
 * Free a JSON object.
 */
static void
tmm_json_object_free(struct tmm_json_object *obj)
{
    struct json_keyval *kv;
    struct json_keyval *kvtmp;

    DBG_ASSERT("not NULL", obj != NULL);
    TAILLIST_FOREACH2(kv, kvtmp, &obj->kvps, next) {
        TAILLIST_REMOVE(&obj->kvps, kv, next);
        tmm_json_keyval_free(kv);
    }
    umem_cache_free(tmm_json_object_cache, obj);
}

/*
 * Allocate a new JSON array. Return NULL if out of memory.
 */
static struct tmm_json_array *
tmm_json_array_alloc(void)
{
    struct tmm_json_array *ary;

    ary = umem_cache_alloc(tmm_json_array_cache, 0);
    if (ary != NULL) {
        memset(ary, 0, sizeof(struct tmm_json_array));
    }
    return ary;
}

/*
 * Free a JSON array.
 */
static void
tmm_json_array_free(struct tmm_json_array *ary)
{
    struct tmm_json_value *val;
    unsigned i;

    DBG_ASSERT("not NULL", ary != NULL);
    if (ary->vals == NULL) {
        goto done;
    }
    for (i = 0; i < ary->nvals; i++) {
        val = (*ary->vals)[i];
        if (val != NULL) {
            tmm_json_value_release(val);
        }
    }
    ufree(ary->vals);

done:
    umem_cache_free(tmm_json_array_cache, ary);
    return;
}

/*
 * Clear a value of any allocated item it contains, and set type invalid.
 * This convenience function Leaves the value in an inconsistent state.
 * Caller must assign a new type and value immediately, and adjust flags.
 */
static void
tmm_json_value_clear(struct tmm_json_value *val)
{
    DBG_ASSERT("not NULL", val != NULL);
    switch (val->type) {
    case JSON_TYPE_OBJECT:
        tmm_json_object_free(val->value.o);
        break;
    case JSON_TYPE_ARRAY:
        tmm_json_array_free(val->value.a);
        break;
    case JSON_TYPE_STRING:
    case JSON_TYPE_LITERAL:
        if (val->allocd) {
            ufree(val->value.s.base);
        }
        break;
    default:
        break;
    };
    val->type = JSON_TYPE_INVALID;
}

/*
 * Free a JSON value and all the items it contains.
 */
static void
tmm_json_value_release(struct tmm_json_value *val)
{
    tmm_json_value_clear(val);
    tmm_json_value_free(val);
}


/******************************************************************************
 * Operations on the Cache.
 */

/*
 * Index a JSON object from a token. That is, create the tmm_json_object
 * structure filled with information from the token, ready for parsing.
 * Do not parse its content - that will be done on demand by
 * tmm_json_cache_parse_object().
 * The 'parent' is the containing tmm_json_value for indexing contained values.
 * If successful, set *objp, else return an error code.
 */
static err_t
tmm_json_cache_index_object(struct tmm_json_cache *json, unsigned tokidx,
        struct tmm_json_value *parent, struct tmm_json_object **objp)
{
    struct tmm_json_object *obj;
    err_t err = ERR_OK;

    obj = tmm_json_object_alloc();
    ERR_MEM(obj, err, out);

    obj->tokidx = tokidx;
    TAILLIST_INIT(&obj->kvps);
    obj->json = json;
    obj->parent = parent;

    *objp = obj;

out:
    return err;
}

/*
 * Index a JSON array from a token. That is, create the tmm_json_array structure
 * filled with information from the token, ready for parsing. Do not parse its
 * content - that will be done on demand by tmm_json_cache_parse_array().
 * The 'parent' is the containing tmm_json_value for indexing contained values.
 * If successful, set *aryp, else return an error code.
 */
static err_t
tmm_json_cache_index_array(struct tmm_json_cache *json, unsigned tokidx,
        struct tmm_json_value *parent, struct tmm_json_array **aryp)
{
    struct tmm_json_array *ary;
    err_t err = ERR_OK;

    ary = tmm_json_array_alloc();
    ERR_MEM(ary, err, out);
    ary->tokidx = tokidx;
    ary->json = json;
    ary->parent = parent;

    *aryp = ary;

out:
    return err;
}


/*
 * Index a JSON value from a token. That is, create the tmm_json_value structure
 * filled with information from the token, ready for parsing. Do not parse
 * its content - that will be done on demand by tmm_json_cache_parse_value().
 * Set the value's owner (parent), which is the value this is part of.
 * If successful, set *valp, else return an error code.
 */
static err_t
tmm_json_cache_index_value(struct tmm_json_cache *json, unsigned tokidx,
        struct tmm_json_value *owner, struct tmm_json_value **valp)
{
    struct tmm_json_value *val;
    err_t err = ERR_OK;

    val = tmm_json_value_alloc();
    ERR_MEM(val, err, out);

    val->tokidx = tokidx;
    val->json = json;
    val->owner = owner;
    val->parsed = FALSE;
    *valp = val;

out:
    return err;
}

/*
 * Parse a JSON object. That is, represent its content in a manner that can
 * be returned in a 'get' function, or operated on. Index contained values.
 */
static err_t
tmm_json_cache_parse_object(struct tmm_json_object *obj)
{
    struct tmm_json_cache *json = obj->json;
    UINT32 tokidx = obj->tokidx;
    jxmntok_t *tok;
    struct json_keyval *kv;
    struct json_keyval *kvtmp;
    unsigned nkvps;
    unsigned i;
    err_t err = ERR_OK;

    if (obj->parsed) {
        goto out;
    }
    tok = &(*json->tokens)[tokidx++];
    nkvps = tok->size;
    for (i = 0; i < nkvps; i++) {
        kv = tmm_json_keyval_alloc();
        ERR_MEM(kv, err, fail);
        /* Key. Index, but do not parse (will be done on demand). */
        kv->key_parsed = FALSE;
        kv->key_tokidx = tokidx;
        tok = &(*json->tokens)[tokidx++];
        if (tok->type != JXMN_STRING) {
            tmm_json_keyval_free(kv);
            err = ERR_TYPE;
            goto fail;
        }
        /* Value. */
        err = tmm_json_cache_index_value(json, tokidx, obj->parent, &kv->value);
        if (err != ERR_OK) {
            tmm_json_keyval_free(kv);
            err = ERR_VAL;
            goto fail;
        }
        tokidx = (*json->tokens)[tokidx].sibling; /* Skip to next key token */
        if (unlikely(tokidx < 0)) {
            /* Shouldn't ever happen. Means a sibling didnt get set by jxmn */
            err = ERR_UNKNOWN;
            goto fail;
        }
        TAILLIST_INSERT_TAIL(&obj->kvps, kv, next);
    }
    obj->nkvps = nkvps;
    obj->parsed = TRUE;
    goto out;

fail:
    TAILLIST_FOREACH2(kv, kvtmp, &obj->kvps, next) {
        TAILLIST_REMOVE(&obj->kvps, kv, next);
        tmm_json_keyval_free(kv);
    }

out:
    return err;
}


/*
 * Parse a JSON array. That is, represent its content in a manner that can
 * be returned in a 'get' function, or operated on. Index contained values.
 */
static err_t
tmm_json_cache_parse_array(struct tmm_json_array *ary)
{
    struct tmm_json_cache *json = ary->json;
    UINT32 tokidx = ary->tokidx;
    jxmntok_t *tok;
    struct tmm_json_value *val;
    unsigned nvals;
    unsigned nchunks;
    unsigned i;
    SIZE alloc_size;
    err_t err = ERR_OK;

    if (ary->parsed) {
        goto out;
    }
    tok = &(*json->tokens)[tokidx++];
    nvals = tok->size;
    if (nvals == 0) {
        ary->vals = NULL;
        nchunks = 0;
    } else {
        nchunks = 1 + ((nvals - 1) / JSON_ARRAY_CHUNK_SIZE);
        /*
         * Check for integer overflow in allocation size calculation.
         * The multiplication nchunks * JSON_ARRAY_CHUNK_SIZE * sizeof(ptr)
         * could wrap around for very large attacker-controlled nvals values,
         * resulting in a small allocation followed by a heap buffer overflow.
         */
        if (nchunks > ((SIZE)(-1) /
                (JSON_ARRAY_CHUNK_SIZE * sizeof(struct tmm_json_value *)))) {
            err = ERR_TOOBIG;
            goto out;
        }
        alloc_size = (SIZE)nchunks * JSON_ARRAY_CHUNK_SIZE *
                sizeof(struct tmm_json_value *);
        ary->vals = umalloc(alloc_size, M_JSON, 0);
        ERR_MEM(ary->vals, err, out);
    }
    for (i = 0; i < nvals; i++) {
        err = tmm_json_cache_index_value(json, tokidx, ary->parent, &val);
        if (err != ERR_OK) {
            err = ERR_VAL;
            goto fail;
        }
        (*ary->vals)[i] = val;
        tokidx = (*json->tokens)[tokidx].sibling; /* Skip to next val tok */
        if (unlikely(tokidx < 0)) {
            /* Shouldn't ever happen. Means a sibling didnt get set by jxmn */
            err = ERR_UNKNOWN;
            goto fail;
        }
    }
    ary->nvals = nvals;
    ary->nchunks = nchunks;
    ary->parsed = TRUE;
    goto out;

fail:
    for (i = 0; i < ary->nvals; i++) {
        val = (*ary->vals)[i];
        if (val != NULL) {
            tmm_json_value_free(val);
        }
    }
    ufree(ary->vals);
    ary->vals = NULL;

out:
    return err;
}

/*
 * Parse a JXMN primitive. This includes JSON numbers, booleans and 'null'.
 * Only handle integers that fit in 64 bits signed. Other literals that
 * start out looking like numbers (begin with a decimal digit or '-' sign)
 * are passed through as literals without further parsing (not strings).
 */
static err_t
tmm_json_cache_parse_jxmn_primitive(struct tmm_json_value *val, jxmntok_t *tok)
{
    struct xbuf *raw = &val->json->raw;
    xcursor_t cur;
    size_t len;
    char tokval[23];    /* Longest 64-bit int + room for '-', '.' & '\0'. */
    char *ep;
    INT64 num;
    unsigned toklen = tok->end - tok->start;
    err_t err = ERR_OK;

    if (!val->json->raw_valid) {
        /* Can't access this data anymore. Probably already rendered */
        err = ERR_VERBOTEN;
        goto out;
    }

    cur = xbuf_begin(raw);
    err = xbuf_move(raw, &cur, tok->start);
    len = xbuf_extract(raw, cur, tokval, sizeof(tokval) - 1, NULL);
    if (len < toklen) {
        err = ERR_TYPE;
        goto out;
    }
    tokval[toklen] = '\0';

    if (isdigit(tokval[0]) || (tokval[0] == '-')) {
        /* It's a number. */
        errno = EOK;
        num = strtoll(tokval, &ep, 10);
        if ((ep != tokval) && (*ep == '\0') && (errno == EOK)) {
            /* Valid decimal integer that fits in 64 bits signed. */
            val->type = JSON_TYPE_INTEGER;
            val->value.i = num;
            goto out;
        }
        /* Not a JSON error, just can't be represented as a 64 bit integer. */
        val->type = JSON_TYPE_LITERAL;
        goto out;
    }

    /* It's an unquoted literal (not a string or numnber). */
    if (strncmp(tokval, "null", toklen) == 0) {
        val->type = JSON_TYPE_NULL;
        goto out;
    }
    if (strncmp(tokval, "false", toklen) == 0) {
        val->type = JSON_TYPE_BOOL;
        val->value.b = FALSE;
        goto out;
    }
    if (strncmp(tokval, "true", toklen) == 0) {
        val->type = JSON_TYPE_BOOL;
        val->value.b = TRUE;
        goto out;
    }
    #ifdef JSON_PASS_UNKNOWN_LITERALS   /* XXX: Do we want this as an option? */
    val->type = JSON_TYPE_LITERAL;
    #else
    val->type = JSON_TYPE_INVALID;
    err = ERR_TYPE;
    #endif

out:
    return err;
}

/*
 * Allocate space and copy the string from the JSON
 * script, removing any escape sequences.
 */
static err_t
tmm_json_cache_parse_string_helper(struct xbuf *raw, int start,
        unsigned toklen, BYTE **out_buf, unsigned *out_len)
{
    BYTE *buf = NULL;
    xcursor_t cur;
    unsigned len;
    err_t err = ERR_OK;

    buf = umalloc(toklen + 1, M_JSON, 0);
    ERR_MEM(buf, err, out);

    cur = xbuf_begin(raw);
    err = xbuf_move(raw, &cur, start);
    len = xbuf_extract(raw, cur, buf, toklen, NULL);
    if (len < toklen) {
        err = ERR_BUF;
        ufree(buf);
        goto out;
    }
    buf[toklen] = '\0';

    *out_buf = buf;
    *out_len = len;

out:
    return err;
}


/*
 * Parse a JSON string (surrounding quotes have been removed by tokenizer).
 * Literals are also treated as strings.
 */
static err_t
tmm_json_cache_parse_string(struct tmm_json_value *val)
{
    struct tmm_json_cache *json = val->json;
    struct xbuf *raw;
    jxmntok_t *tok;
    unsigned toklen;
    BYTE *buf = NULL;
    unsigned len = 0;
    err_t err = ERR_OK;

    DBG_ASSERT("Value is string", (val->type == JSON_TYPE_STRING) ||
            (val->type == JSON_TYPE_LITERAL));
    if (val->allocd) {
        goto out;
    }
    if (!json->raw_valid) {
        /* Can't parse raw data anymore. Probably already rendered */
        err = ERR_VERBOTEN;
        goto out;
    }
    raw = &val->json->raw;
    tok = &(*json->tokens)[val->tokidx];
    toklen = tok->end - tok->start;

    err = tmm_json_cache_parse_string_helper(raw, tok->start, toklen, &buf, &len);
    val->value.s.base = buf;
    val->value.s.len = len;
    val->allocd = TRUE;

out:
    return err;
}

/*
 * Parse a JSON value. That is, represent its content in a manner that can be
 * returned in a 'get' function, or operated on. If this is a collection (JSON
 * object or array), index the tmm_json_object or tmm_json_array structure.
 */
static err_t
tmm_json_cache_parse_value(struct tmm_json_value *val)
{
    struct tmm_json_cache *json = val->json;
    UINT32 tokidx = val->tokidx;
    jxmntok_t *tok;
    err_t err = ERR_OK;

    if (val->parsed || (json == NULL) || (json->tokens == NULL)) {
        goto out;
    }
    tok = &(*json->tokens)[tokidx];

    switch (tok->type) {
    case JXMN_OBJECT:
        val->type = JSON_TYPE_OBJECT;
        err = tmm_json_cache_index_object(json, tokidx, val, &val->value.o);
        ERR(err, out);
        val->allocd = TRUE;
        break;
    case JXMN_ARRAY:
        val->type = JSON_TYPE_ARRAY;
        err = tmm_json_cache_index_array(json, tokidx, val, &val->value.a);
        ERR(err, out);
        val->allocd = TRUE;
        break;
    case JXMN_PRIMITIVE:    /* Numbers and literals. */
        err = tmm_json_cache_parse_jxmn_primitive(val, tok);
        break;
    case JXMN_STRING:
        /* Quotes have been removed by JXMN. */
        val->type = JSON_TYPE_STRING;
        break;
    case JXMN_UNDEFINED:
    default:
        /* Should not happen. */
        val->type = JSON_TYPE_INVALID;
        err = ERR_TYPE;
        break;
    }
    val->parsed = TRUE;

out:
    return err;
}

/*
 * Parse a JSON key (surrounding quotes have been removed by tokenizer).
 */
static err_t
tmm_json_cache_parse_key(struct json_keyval *kv, struct tmm_json_cache *json)
{
    struct xbuf *raw;
    jxmntok_t *tok;
    unsigned toklen;
    BYTE *buf = NULL;
    unsigned len = 0;
    err_t err = ERR_OK;

    if (kv->key_alloc || kv->key_parsed) {
        goto out;
    }
    if (!json->raw_valid) {
        /* Can't parse raw data anymore. Probably already rendered */
        err = ERR_VERBOTEN;
        goto out;
    }
    raw = &json->raw;
    tok = &(*json->tokens)[kv->key_tokidx];
    toklen = tok->end - tok->start;

    err = tmm_json_cache_parse_string_helper(raw, tok->start, toklen, &buf,
            &len);
    kv->key.base = buf;
    kv->key.len = len;
    kv->key_alloc = TRUE;
    kv->key_parsed = TRUE;

out:

    return err;

}

/*******************************************************************************
 * Interface Functions: Operations on a JSON Cache.
 * Descriptions are in the header json_parse.h .
 */

err_t
tmm_json_cache_create(struct tmm_json_cache **jsonp, UINT32 token_limit,
        UINT16 mss)
{
    struct tmm_json_cache *json;
    err_t err = ERR_OK;

    /* XXX: Do we want a umem cache for this too? */
    json = umalloc(sizeof(struct tmm_json_cache), M_JSON, UM_ZERO);
    ERR_MEM(json, err, out);

    json->tok_limit = token_limit;
    json->raw_valid = TRUE;
    xbuf_embed_init(&json->raw, mss);
    *jsonp = json;
    json->ref = 1;
out:
    return err;
}

struct tmm_json_cache *
tmm_json_cache_addref(struct tmm_json_cache *json)
{
    if (json != NULL) {
        json->ref += 1;
    }

    return json;
}

static err_t
tmm_json_cache_parse_internal(struct tmm_json_cache *json, BOOL eof,
        BOOL *extra_bytes)
{
    struct jxmn_xbuf_loc loc;
    int jres;
    err_t err = ERR_OK;

    DBG_ASSERT("JSON cache not NULL", json != NULL);
    if (extra_bytes != NULL) {
        *extra_bytes = FALSE;
    }

    loc.xc = xbuf_begin(&json->raw);
    loc.pos = 0;
    do {
        /* Run or Resume the JXMN tokenizer. */
        jres = jxmn_parse(&json->jxmn, &json->raw, &loc, &(*json->tokens)[0],
                json->tok_num, eof);
        if (jres == 0) {
            /* 
             * Syntactically valid parse, but nothing of substance
             * found yet. No root value to index at this point.
            */
            goto out;
        } else if ((jres > 0) || (jres == JXMN_ERROR_EXTRA)) {
            /* Success. Index the root value to be ready for parsing. */
            if (json->root != NULL) {
                tmm_json_value_release(json->root);
                json->root = NULL;
            }
            err = tmm_json_cache_index_value(json, 0, NULL, &json->root);
            ERR(err, out);
            if (extra_bytes != NULL) {
                *extra_bytes = (jres == JXMN_ERROR_EXTRA);
            }
            goto out;
        }
        switch (jres) {
        case JXMN_ERROR_NOMEM:
            /* Out of tokens. Grow the token array, but not past the limit. */
            if (json->tok_num >= json->tok_limit) {
                err = ERR_TOOBIG;
                break;
            }
            json->tok_num = MIN(json->tok_num + TOK_GROW_INCR,
                    json->tok_limit);
            json->tokens = urealloc(json->tokens,
                    json->tok_num * sizeof(jxmntok_t), M_JSON, 0);
            if (json->tokens == NULL) {
                err = ERR_MEM;
            }
            break;
        case JXMN_ERROR_PART:
            err = ERR_MORE_DATA;
            break;
        case JXMN_ERROR_INVAL:
            err = ERR_REJECT;
            break;
        default:
            err = ERR_UNKNOWN;
            break;
        }

    } while (err == ERR_OK);

out:
    return err;
}

err_t
tmm_json_cache_parse_xbuf(struct tmm_json_cache *json, struct xbuf *script,
        BOOL *extra_bytes)
{
    err_t err = ERR_OK;

    if ((json == NULL) || (script == NULL)) {
        err = ERR_VAL;
        goto out;
    }

    xbuf_merge(&json->raw, script);

    /*
     * Tokenize the JSON script.
     * How many tokens will we need? Guess bytes per token, add a
     * whole bunch of padding, make it at least 1 grow increment,
     * and respect the token limit.
     */
    if (json->tokens == NULL) {
        json->tok_num = MIN(
                MAX(json->raw.len / (TOK_AVG_BYTES >> 2), TOK_GROW_INCR),
                json->tok_limit);
        json->tokens = umalloc(json->tok_num * sizeof(jxmntok_t), M_JSON, 0);
        ERR_MEM(json->tokens, err, out);
        jxmn_init(&json->jxmn);
    }

    err = tmm_json_cache_parse_internal(json, FALSE, extra_bytes);

out:
    return err;
}

err_t
tmm_json_cache_parse_complete(struct tmm_json_cache *json)
{
    err_t err = ERR_OK;

    if (json == NULL) {
        err = ERR_VAL;
        goto out;
    }

    if (json->tokens == NULL) {
        /* Never init'ed tokens for parsing - then quietly skip parsing */
        goto out;
    }

    err = tmm_json_cache_parse_internal(json, TRUE, NULL);

out:
    return err;
}

BOOL
tmm_json_cache_is_empty(struct tmm_json_cache *json)
{
    return (json->root == NULL);
}

void
tmm_json_cache_release(struct tmm_json_cache *json)
{
    if (json != NULL) {
        json->ref -= 1;
        if (json->ref > 0) {
            goto out;
        }
        if (json->root != NULL) {
            tmm_json_value_release(json->root);
        }
        ufree(json->tokens);
        xbuf_free(&json->raw);
        ufree(json);
    }
out:
    return;
}

/*
 * Helper function to insert in xb and move cursor to end of inserted data
 */
static inline err_t
xbuf_insert_move(struct xbuf *xb, xcursor_t *xcur, const void *data, int len)
{
    err_t err;

    err = xbuf_insert(xb, xcur, data, len);
    if (err == ERR_OK) {
        err = xbuf_move(xb, xcur, len);
    }

    return err;
}

static err_t
tmm_json_cache_render_passthru(struct xbuf *dst, struct tmm_json_cache *json,
        int tokidx, xcursor_t *cur, int *tok_pos)
{
    jxmntok_t *tok = &(*json->tokens)[tokidx];
    int toklen = tok->end - tok->start;
    err_t err = ERR_OK;

    /*
    * Move cursor past raw tokenized data in xbuf to effectively
    * add the content to the rendered json BEHIND the cursor. If there
    * is any data between the current cur position and the location of
    * the data, we delete it since it must have been removed or insignificant.
    * NOTE: To passthru a string token type, we need to add quote marks.
    */

    if (tok->type == JXMN_STRING) {
        err = xbuf_insert_move(dst, cur, "\"", 1);
        ERR(err, out);
    }

    if (*tok_pos < tok->start) {
        /* Dump unused/removed data between render pos and this token */
        err = xbuf_delete(dst, cur, tok->start - *tok_pos);
    } else if (*tok_pos > tok->start) {
        /*
         * Should never happen. This is bad. Some unparsed token
         * must have been moved in the json tree. We already rendered past
         * this token and overwrote it so we can't read it anymore.
         */
        err = ERR_UNKNOWN;
    }

    ERR(err, out);

    err = xbuf_move(dst, cur, toklen);
    ERR(err, out);
    *tok_pos = tok->end;

    if (tok->type == JXMN_STRING) {
        err = xbuf_insert_move(dst, cur, "\"", 1);
    }

out:
    return err;
}

/*
 * Helper function to render a value and (recursively) its children
 */
static err_t
tmm_json_cache_render_value(struct xbuf *dst, struct tmm_json_value *val,
        xcursor_t *cur, int *tok_pos)
{
    struct tmm_json_cache *cache = val->json;
    char intbuf[23]; /* Longest 64-bit int + room for '-', '.' & '\0'. */
    int intlen;
    int idx;
    struct json_keyval *kv;
    err_t err = ERR_OK;

    /* PASSTHRU this value */
    if (!val->edited) {
        err = tmm_json_cache_render_passthru(dst, cache, val->tokidx, cur,
                tok_pos);
        goto out;
    }

    /* Not passing thru this value. Actually render it by type */
    switch (val->type) {
    case JSON_TYPE_OBJECT:

        /* Make sure this object has had its list filled in */
        err = tmm_json_cache_parse_object(val->value.o);
        ERR(err, out);

        err = xbuf_insert_move(dst, cur, "{", 1);
        ERR(err, out);

        /* Render key value pairs in this object */
        TAILLIST_FOREACH(kv, &val->value.o->kvps, next) {

            err = xbuf_insert_move(dst, cur, " ", 1);
            ERR(err, out);

            /* If val at this kv is edited, render key from parsed string */
            if (kv->value->edited) {
                err = xbuf_insert_move(dst, cur, "\"", 1);
                ERR(err, out);
                err = xbuf_insert_move(dst, cur, kv->key.base,
                        kv->key.len);
                ERR(err, out);
                err = xbuf_insert_move(dst, cur, "\"", 1);
            } else {
                err = tmm_json_cache_render_passthru(dst, cache,
                        kv->key_tokidx, cur, tok_pos);
            }
            ERR(err, out);

            err = xbuf_insert_move(dst, cur, ": ", 2);
            ERR(err, out);
            err = tmm_json_cache_render_value(dst, kv->value, cur, tok_pos);
            ERR(err, out);
            err = xbuf_insert_move(dst, cur, ",", 1);
            ERR(err, out);
        }

        /* If we wrote at least 1 entry, replace the last ',' with ' ' */
        if (!TAILLIST_EMPTY(&val->value.o->kvps)) {
            err = xbuf_move(dst, cur, -1);
            ERR(err, out);
            if (xbuf_replace(dst, *cur, " ", 1) != 1) {
                err = ERR_UNKNOWN;
                goto out;
            }
            ERR(err, out);
            err = xbuf_move(dst, cur, 1);
            ERR(err, out);
        }

        err = xbuf_insert_move(dst, cur, "}", 1);
        ERR(err, out);

        break;

    case JSON_TYPE_ARRAY:

        /* Make sure this array has had its list filled in */
        err = tmm_json_cache_parse_array(val->value.a);
        ERR(err, out);

        err = xbuf_insert_move(dst, cur, "[", 1);
        ERR(err, out);

        /* Render values contained in this array */
        for (idx = 0; idx < val->value.a->nvals; idx++) {
            err = xbuf_insert_move(dst, cur, " ", 1);
            ERR(err, out);
            err = tmm_json_cache_render_value(dst,
                    (*(val->value.a->vals))[idx], cur, tok_pos);
            ERR(err, out);
            err = xbuf_insert_move(dst, cur, ",", 1);
            ERR(err, out);
        }

        /* If at least 1 value was written, replace last ',' with ' ' */
        if (val->value.a->nvals > 0) {
            err = xbuf_move(dst, cur, -1);
            ERR(err, out);
            if (xbuf_replace(dst, *cur, " ", 1) != 1) {
                err = ERR_UNKNOWN;
                goto out;
            }
            ERR(err, out);
            err = xbuf_move(dst, cur, 1);
            ERR(err, out);
        }

        xbuf_insert_move(dst, cur, "]", 1);
        ERR(err, out);

        break;

    case JSON_TYPE_NULL:
        /* Insert the string null */
        err = xbuf_insert_move(dst, cur, "null", 4);
        ERR(err, out);
        break;

    case JSON_TYPE_STRING:
        /* Insert the string content encased in double quote marks */
        err = xbuf_insert_move(dst, cur, "\"", 1);
        ERR(err, out);
        err = xbuf_insert_move(dst, cur, val->value.s.base,
                val->value.s.len);
        ERR(err, out);
        err = xbuf_insert_move(dst, cur, "\"", 1);
        ERR(err, out);
        break;

    case JSON_TYPE_INTEGER:
        /* Print integer to char buffer and then insert to xbuf */
        intlen = sprintf(intbuf, "%lld", val->value.i);
        err = xbuf_insert_move(dst, cur, intbuf, intlen);
        ERR(err, out);
        break;

    case JSON_TYPE_BOOL:
        /* Insert the string true or false depending on the value */
        if (val->value.b) {
            err = xbuf_insert_move(dst, cur, "true", 4);
            ERR(err, out);
        } else {
            err = xbuf_insert_move(dst, cur, "false", 5);
            ERR(err, out);
        }
        break;

    case JSON_TYPE_LITERAL:
        /* Print literal content, without quotes as string types have */
        err = xbuf_insert_move(dst, cur, val->value.s.base,
                val->value.s.len);
        ERR(err, out);
        break;

    default:
        err = ERR_TYPE;
        goto out;
    }

out:
    return err;
}

err_t
tmm_json_cache_render_xbuf(struct tmm_json_cache *json, struct xbuf *dst)
{
    /*
     * This implementation is intended to minimize copying of data when
     * possible. The rendered xbuf will be assembled inline within the original
     * raw json data xbuf. This allows us to insert and delete segments
     * where changes have occurred while leaving untouched values in the
     * xbuf to avoid having to perform copy operations. The resulting data
     * will then be quickly xbuf_merge'd into the dst supplied. As this
     * essentially 'consumes' the inline data, we can only render each cache
     * ONCE using this function.
     *
     * Each tmm_json_value struct has an 'edited' flag to track if it has been
     * altered in some way and must be fully rendered to the xbuf, or is
     * untouched and can be passed thru from its original tokenization.
     *
     * In order for this quick rendering to succeed, we MUST operate on the
     * principle that any values dependent on their original tokenization,
     * i.e. values that do not have 'edited' set and will be passed thru,
     * must be encountered in the rendering sweep in the same order as they
     * appear in the raw buffer. Values with 'edited' set may be inserted
     * anywhere in the json tree, and values may be deleted anywhere since
     * these operations do not flip-flop the ordering of any token-dependent
     * passthru values. Since the original parsing fills the json
     * tree in order, we just have to be certain no get/set operations are
     * performed that could lead to any value or child value being moved out
     * of order, unless if said value and all of its token-dependent children
     * are parsed and marked as 'edited' to remove their token dependence.
     *
     * The rendering is performed using a recursive function to render
     * each value and its 'edited' children (if it's a collection type).
     * A cursor is kept to move through the original xbuf inserting and
     * deleting data as needed. All data behind this cursor has been rendered,
     * (tokenization is invalid). All data ahead of the cursor is still
     * the original raw data and is valid for tokens. To track the location
     * of the cursor relative to the original tokenization, the tok_pos
     * variable is used. tok_pos tracks the equivalent index of the cursor
     * when looking forward for tokenization. For example, even if xcur is at
     * index 40 in the xbuf (we already inserted some data behind it). If
     * tok_pos is 20, and we want to access a value tokenized at index 30,
     * we can be sure that tokenized value is untouched 10 bytes ahead of xcur.
     */

    err_t err = ERR_OK;
    xcursor_t cur;
    int tok_pos = 0;

    if (json == NULL || dst == NULL) {
        err = ERR_VAL;
        goto out;
    }

    if (json->root == NULL) {
        /* Leave the xbuf untouched - no content */
        goto out;
    }

    if (!json->raw_valid) {
        /* Can't render inline anymore. Probably already rendered */
        err = ERR_VERBOTEN;
        goto out;
    }
    json->raw_valid = FALSE;

    /* Render the json tree inline in json->raw */
    cur = xbuf_begin(&json->raw);
    err = tmm_json_cache_render_value(&json->raw, json->root, &cur, &tok_pos);
    ERR(err, out);
    /* Remove any tailing content beyond the end of the JSON. */
    err = xbuf_delete_after(&json->raw, &cur);
    ERR(err, out);

    /* Done rendering inline. Quickly merge onto tail of dst */
    xbuf_merge(dst, &json->raw);

out:
    return err;
}

err_t
tmm_json_cache_get_root(struct tmm_json_cache *json,
        struct tmm_json_value **valp)
{
    struct tmm_json_value *val;
    err_t err = ERR_OK;

    if ((json == NULL) || (valp == NULL)) {
        err = ERR_VAL;
        goto out;
    }
    if (json->root == NULL) {
        val = tmm_json_value_alloc();
        ERR_MEM(val, err, out);

        val->edited = TRUE; /* Generated root value, not parsed via jxmn */
        val->parsed = TRUE; /* Prevent attempts to parse a generated val */
        val->allocd = TRUE;
        val->json = json;
        json->root = val;
    }
    *valp = json->root;
out:
    return err;
}

UINT32
tmm_json_cache_tokens_used(struct tmm_json_cache *json)
{
    return (json != NULL) ? json->jxmn.toknext : 0;
}

SIZE
tmm_json_cache_size_raw(struct tmm_json_cache*json)
{
    return ((json != NULL) && (json->raw_valid)) ? json->raw.len : 0;
}

void
tmm_json_cache_recover_raw(struct tmm_json_cache *json,
        struct xbuf *merge_dst)
{
    DBG_ASSERT("JSON cache not NULL", json != NULL);
    DBG_ASSERT("Merge destination xbuf not NULL", merge_dst != NULL);

    if (json->raw_valid) {
        xbuf_merge(merge_dst, &json->raw);
        json->raw_valid = FALSE;
    }
}

err_t
tmm_json_cache_copy_raw(struct tmm_json_cache *json, struct xbuf *dst)
{
    struct xbuf tmp;
    err_t err = ERR_OK;

    if ((json == NULL) || (dst == NULL)) {
        err = ERR_VAL;
        goto out;
    }

    if (!json->raw_valid) {
        /* Can't copy anymore. Probably already rendered */
        err = ERR_VERBOTEN;
        goto out;
    }

    /* Duplicate the whole raw xbuf */
    xbuf_embed_init(&tmp, dst->mss);
    err = xbuf_clone(&tmp, &json->raw);
    if (err != ERR_OK) {
        goto out;
    }

    /* Append duplicated xbuf to end of dst param */
    xbuf_merge(dst, &tmp);

out:
    return err;
}

err_t
tmm_json_cache_copy(struct tmm_json_cache **dst, struct tmm_json_cache *src)
{
    struct xbuf xb;
    struct tmm_json_cache *json_copy;
    err_t err = ERR_OK;

    if (src == NULL) {
        err = ERR_VAL;
        goto out;
    }

    xbuf_embed_init(&xb, src->raw.mss);

    err = tmm_json_cache_create(&json_copy, src->tok_limit, src->raw.mss);
    if (err != ERR_OK) {
        goto out;
    }

    err = tmm_json_cache_copy_raw(src, &xb);
    if (err != ERR_OK) {
        tmm_json_cache_release(json_copy);
        goto out;
    }

    err = tmm_json_cache_parse_xbuf(json_copy, &xb, NULL);
    if (err == ERR_MORE_DATA) {
        /* Try forcing parser to see end of buffer as full payload */
        err = tmm_json_cache_parse_complete(json_copy);
    }
    if (err != ERR_OK) {
        tmm_json_cache_release(json_copy);
        goto out;
    }

    *dst = json_copy;

out:
    return err;
}

/*******************************************************************************
 * Interface Functions: Operations on a JSON Value.
 * Descriptions are in the header json_parse.h .
 */

enum tmm_json_type
tmm_json_value_type(struct tmm_json_value *val)
{
    return ((val != NULL) && (tmm_json_cache_parse_value(val) == ERR_OK)) ?
            val->type : JSON_TYPE_INVALID;
}

/* Parse value and check type. Common code shared by value 'get' functions. */
static err_t
tmm_json_value_check_type(struct tmm_json_value *val, enum tmm_json_type t)
{
    err_t err = tmm_json_cache_parse_value(val);

    ERR(err, out);
    if (val->type != t) {
        err = ERR_TYPE;
    }
out:
    return err;
}

struct tmm_json_cache *
tmm_json_value_get_cache(struct tmm_json_value *val)
{
    struct tmm_json_cache *json;

    if (val == NULL) {
        json = NULL;
        goto out;
    }
    json = val->json;

out:
    return json;
}

err_t
tmm_json_value_get_object(struct tmm_json_value *val,
        struct tmm_json_object **objp)
{
    err_t err = ERR_OK;

    err = tmm_json_value_check_type(val, JSON_TYPE_OBJECT);
    ERR(err, out);
    *objp = val->value.o;
out:
    return err;
}

err_t
tmm_json_value_get_array(struct tmm_json_value *val,
        struct tmm_json_array **aryp)
{
    err_t err = ERR_OK;

    err = tmm_json_value_check_type(val, JSON_TYPE_ARRAY);
    ERR(err, out);
    *aryp = val->value.a;
out:
    return err;
}

err_t
tmm_json_value_get_string(struct tmm_json_value *val,
        struct tmm_json_string *str)
{
    err_t err = ERR_OK;

    err = tmm_json_value_check_type(val, JSON_TYPE_STRING);
    ERR(err, out);
    err = tmm_json_cache_parse_string(val);
    ERR(err, out);
    str->base = val->value.s.base;
    str->len  = val->value.s.len;
out:
    return err;
}

err_t
tmm_json_value_get_literal(struct tmm_json_value *val,
        struct tmm_json_string *str)
{
    err_t err = ERR_OK;

    err = tmm_json_value_check_type(val, JSON_TYPE_LITERAL);
    ERR(err, out);
    err = tmm_json_cache_parse_string(val);
    ERR(err, out);
    str->base = val->value.s.base;
    str->len  = val->value.s.len;
out:
    return err;
}

err_t
tmm_json_value_get_integer(struct tmm_json_value *val, INT64 *num)
{
    err_t err = ERR_OK;

    err = tmm_json_value_check_type(val, JSON_TYPE_INTEGER);
    ERR(err, out);
    *num = val->value.i;
out:
    return err;
}

err_t
tmm_json_value_get_bool(struct tmm_json_value *val, BOOL *b)
{
    err_t err = ERR_OK;

    err = tmm_json_value_check_type(val, JSON_TYPE_BOOL);
    ERR(err, out);
    *b = val->value.b;
out:
    return err;
}

err_t
tmm_json_value_set_object(struct tmm_json_value *val,
        struct tmm_json_object **objp)
{
    struct tmm_json_object *obj;
    err_t err = ERR_OK;

    if (val == NULL) {
        err = ERR_VAL;
        goto out;
    }

    /* Create a and init a new empty object. */
    obj = tmm_json_object_alloc();
    ERR_MEM(obj, err, out);

    TAILLIST_INIT(&obj->kvps);
    obj->parsed = TRUE;
    obj->json = val->json;
    obj->parent = val;

    /* Replace the old value with the new object. */
    tmm_json_value_clear(val);
    val->type = JSON_TYPE_OBJECT;
    val->value.o = obj;
    val->parsed = TRUE;
    val->allocd = TRUE;
    tmm_json_value_set_edited(val);

    if (objp != NULL) {
        *objp = obj;
    }

out:
    return err;
}

err_t
tmm_json_value_set_array(struct tmm_json_value *val,
        struct tmm_json_array **aryp)
{
    struct tmm_json_array *ary;
    err_t err = ERR_OK;

    if (val == NULL) {
        err = ERR_VAL;
        goto out;
    }

    /* Create and init a new empty array. */
    ary = tmm_json_array_alloc();
    ERR_MEM(ary, err, out);

    ary->parsed = TRUE;
    ary->json = val->json;
    ary->parent = val;

    /* Replace the old value with the new array. */
    tmm_json_value_clear(val);
    val->type = JSON_TYPE_ARRAY;
    val->value.a = ary;
    val->parsed = TRUE;
    val->allocd = TRUE;
    tmm_json_value_set_edited(val);

    if (aryp != NULL) {
        *aryp = ary;
    }

out:
    return err;
}

err_t
tmm_json_value_set_string(struct tmm_json_value *val,
        struct tmm_json_string *str)
{
    char *buf;
    err_t err = ERR_OK;
    unsigned len;

    if ((val == NULL) || (str == NULL)) {
        err = ERR_VAL;
        goto out;
    }

    len = tmm_json_string_count_unescaped(str) + str->len;

    /* Copy the new string. */
    /* XXX: Also escape certain chars that need it. */
    buf = umalloc(len + 1, M_JSON, 0);
    ERR_MEM(buf, err, out);

    /* Replace the old value with the new string buffer. */
    tmm_json_value_clear(val);
    val->type = JSON_TYPE_STRING;
    val->value.s.base = buf;
    val->value.s.len = len;

    /* Copy the string to the new string buffer. */
    tmm_json_string_set_with_escapes(&(val->value.s), str);

    /* Set value flags */
    val->parsed = TRUE;
    val->allocd = TRUE;
    tmm_json_value_set_edited(val);

out:
    return err;
}

err_t
tmm_json_value_set_literal(struct tmm_json_value *val,
        struct tmm_json_string *str)
{
    err_t err = tmm_json_value_set_string(val, str);

    if (err == ERR_OK) {
        val->type = JSON_TYPE_LITERAL;
    }
    return err;
}

err_t
tmm_json_value_set_integer(struct tmm_json_value *val, INT64 num)
{
    err_t err = ERR_OK;

    if (val == NULL) {
        err = ERR_VAL;
        goto out;
    }

    /* Replace the old value with the new integer. */
    tmm_json_value_clear(val);
    val->type = JSON_TYPE_INTEGER;
    val->value.i = num;
    val->parsed = TRUE;
    val->allocd = FALSE;
    tmm_json_value_set_edited(val);

out:
    return err;
}

err_t
tmm_json_value_set_bool(struct tmm_json_value *val, BOOL b)
{
    err_t err = ERR_OK;

    if (val == NULL) {
        err = ERR_VAL;
        goto out;
    }

    /* Replace the old value with the new integer. */
    tmm_json_value_clear(val);
    val->type = JSON_TYPE_BOOL;
    val->value.b = b ? TRUE: FALSE;     /* Force to a valid BOOL value. */
    val->parsed = TRUE;
    val->allocd = FALSE;
    tmm_json_value_set_edited(val);

out:
    return err;
}

err_t
tmm_json_value_set_null(struct tmm_json_value *val)
{
    err_t err = ERR_OK;

    if (val == NULL) {
        err = ERR_VAL;
        goto out;
    }

    /* Replace the old value with null. */
    tmm_json_value_clear(val);
    val->type = JSON_TYPE_NULL;
    val->parsed = TRUE;
    val->allocd = FALSE;
    tmm_json_value_set_edited(val);

out:
    return err;
}

err_t
tmm_json_value_equal(struct tmm_json_value *val1, struct tmm_json_value *val2,
        BOOL *equal)
{
    err_t err = ERR_OK;

    if (val1 == NULL || val2 == NULL || equal == NULL) {
        err = ERR_VAL;
        goto out;
    }
    err = tmm_json_cache_parse_value(val2);
    ERR(err, out);
    err = tmm_json_value_check_type(val1, val2->type);
    if (err != ERR_OK) {
        if (err == ERR_TYPE) {
            err = ERR_OK;
            *equal = FALSE;
        }
        goto out;
    }

    switch(val1->type) {
    case JSON_TYPE_ARRAY:
    case JSON_TYPE_OBJECT:
        /* Compare value handles for objects and arrays */
        *equal = (val1 == val2);
        break;

    case JSON_TYPE_LITERAL:
    case JSON_TYPE_STRING:
        /* For literal and string types search for identical content */
        err = tmm_json_cache_parse_string(val1);
        ERR(err, out);
        err = tmm_json_cache_parse_string(val2);
        ERR(err, out);
        if (val1->value.s.len != val2->value.s.len) {
            *equal = FALSE;
            goto out;
        }
        *equal = (strncmp(val1->value.s.base, val2->value.s.base,
                val1->value.s.len) == 0);
        break;

    case JSON_TYPE_INTEGER:
        /* For integers search for identical numeric value */
        *equal = (val1->value.i == val2->value.i);
        break;

    case JSON_TYPE_BOOL:
        /* For bools search for matching boolean content */
        *equal = (val1->value.b == val2->value.b);
        break;

    default:
        *equal = TRUE;
        break;
    }
out:
    return err;
}

err_t
tmm_json_value_copy_string_unescaped(struct tmm_json_value *val,
        struct tmm_json_string *str)
{
    err_t err = ERR_OK;

    if (val->type != JSON_TYPE_STRING) {
        err = ERR_TYPE;
        goto out;
    }
    /* XXX: Copy, removing escape sequences. Then remove ERR_NOT_SUPPORTED. */
    err = ERR_NOT_SUPPORTED;

out:
    return err;
}

err_t
tmm_json_value_create(struct tmm_json_value **valp, struct tmm_json_cache *json)
{
    struct tmm_json_value *val;
    err_t err = ERR_OK;

    if (json == NULL) {
        err = ERR_NOT_SUPPORTED;
        goto out;
    }
    val = tmm_json_value_alloc();
    if (val != NULL) {
        val->json = json;
        *valp = val;
    } else {
        err = ERR_MEM;
    }
out:
    return err;
}

/*
 * Allocate a new key and set the value of a key value pair.
 */
static err_t
tmm_json_keyval_create(struct json_keyval **kvp, const char* key, UINT32 len,
        struct tmm_json_value *val)
{
    struct json_keyval *kv;
    BYTE *buf;
    err_t err = ERR_OK;

    kv = tmm_json_keyval_alloc();
    ERR_MEM(kv, err, out);

    /* Copy the new string. */
    buf = umalloc(len + 1, M_JSON, 0);
    ERR_MEM(buf, err, out);

    memcpy(buf, key, len);
    buf[len] = '\0';

    kv->key.base = buf;
    kv->key.len = len;
    kv->key_parsed = TRUE;
    kv->key_alloc = TRUE;
    kv->value = val;
    *kvp = kv;

out:
    if (err != ERR_OK) {
        if (kv != NULL) {
            tmm_json_keyval_free(kv);
        }
    }
    return err;
}

void
tmm_json_value_destroy(struct tmm_json_value *val)
{
    if (!tmm_json_value_is_owned(val)) {
        tmm_json_value_release(val);
    }
}


/******************************************************************************
 * Interface Functions: Operations on a JSON Object.
 * Descriptions are in the header json_parse.h .
 */

struct tmm_json_cache *
tmm_json_object_get_cache(struct tmm_json_object *obj)
{
    struct tmm_json_cache *json;

    if (obj == NULL) {
        json = NULL;
        goto out;
    }
    json = obj->json;

out:
    return json;
}


err_t
tmm_json_object_size(struct tmm_json_object *obj, UINT32 *size)
{
    err_t err = ERR_OK;

    if (size == NULL) {
        err = ERR_VAL;
        goto out;
    }
    if (obj == NULL) {
        *size = 0;
        goto out;
    }
    err = tmm_json_cache_parse_object(obj);
    ERR(err, out);
    *size = obj->nkvps;
out:
    return err;
}

static void inline
tmm_json_object_set_value(struct tmm_json_value **existing,
        struct tmm_json_value *spawn)
{
    struct tmm_json_value *tmp_val;

    tmp_val = *existing;
    spawn->parsed = TRUE;
    spawn->json = tmp_val->json;
    spawn->owner = tmp_val->owner;
    tmm_json_value_set_edited(spawn);
    *existing = spawn;
    tmm_json_value_release(tmp_val);
}

static inline err_t
tmm_json_object_key_matches(struct json_keyval *kv, struct tmm_json_cache *json,
        const char *key, unsigned key_len)
{
    err_t err = ERR_OK;

    err = tmm_json_cache_parse_key(kv, json);
    ERR(err, out);
    err = ERR_NOT_FOUND;
    if ((kv->key.len == key_len) && (strncmp(kv->key.base, key, key_len) ==
            0)) {
        err = ERR_OK;
    }

out:
    return err;
}

err_t
tmm_json_object_get(struct tmm_json_object *obj, const char *key,
    struct tmm_json_value **val)
{
    void *cursor = NULL;

    return tmm_json_object_get_next(obj, key, &cursor, val);
}

err_t
tmm_json_object_get_next(struct tmm_json_object *obj, const char *key,
        void **cursor, struct tmm_json_value **val)
{
    err_t err = ERR_OK;
    UINT32 key_len = 0;
    struct json_keyval *kv;

    if ((key == NULL) || (cursor == NULL) || (val == NULL) ||
            (obj == NULL)) {
        err = ERR_VAL;
        goto out;
    }

    key_len = strlen(key);
    if (key_len == 0) {
        err = ERR_VAL;
        goto out;
    }

    kv = (struct json_keyval*) *cursor;

    *val = NULL;

    err = tmm_json_cache_parse_object(obj);
    ERR(err, out);

    if (TAILLIST_EMPTY(&obj->kvps)) {
        err = ERR_NOT_FOUND;
        goto out;
    }

    if (kv == NULL) {
        /* Initialize kv to the end to start at the beginning */
        kv = TAILLIST_LAST(&obj->kvps);
    } else {
        err = tmm_json_object_key_matches(kv, obj->json, key, key_len);
        if (err != ERR_OK) {
            err = ERR_ARG;
            goto out;
        }
        if (kv == TAILLIST_LAST(&obj->kvps)) {
            err = ERR_NOT_FOUND;
            goto out;
        }
    }

    do {
        kv = TAILLIST_NEXT(kv, next);
        err = tmm_json_object_key_matches(kv, obj->json, key, key_len);
        if (err == ERR_OK) {
            *cursor = (void*)kv;
            *val = kv->value;
            goto out;
        }
    }
    while (kv != TAILLIST_LAST(&obj->kvps));

    err = ERR_NOT_FOUND;

out:
    if (err == ERR_NOT_FOUND) {
        *cursor = NULL;
    }
    return err;
}

err_t
tmm_json_object_get_next_key(struct tmm_json_object *obj, void **cursor,
        char **key, UINT32 *key_len)
{
    err_t err = ERR_OK;
    struct json_keyval *kv;

    if ((key == NULL) || (key_len == NULL) || (cursor == NULL) ||
            (obj == NULL)) {
        err = ERR_VAL;
        goto out;
    }

    kv = (struct json_keyval*) *cursor;
    err = tmm_json_cache_parse_object(obj);
    ERR(err, out);

    if (TAILLIST_EMPTY(&obj->kvps)) {
        err = ERR_NOT_FOUND;
        goto out;
    }

    if (kv == NULL) {
        /* Initialize kv to the end to start at the beginning */
        kv = TAILLIST_LAST(&obj->kvps);
    } else if (kv == TAILLIST_LAST(&obj->kvps)) {
        *cursor = NULL;
        err = ERR_NOT_FOUND;
        goto out;
    }

    kv = TAILLIST_NEXT(kv, next);
    err = tmm_json_cache_parse_key(kv, obj->json);
    ERR(err, out);

    *cursor = (void*)kv;
    *key = kv->key.base;
    *key_len = kv->key.len;

out:
    return err;
}

err_t
tmm_json_object_get_next_value(struct tmm_json_object *obj, void **cursor,
        struct tmm_json_value **val)
{
    err_t err = ERR_OK;
    struct json_keyval *kv;

    if (val == NULL || cursor == NULL || obj == NULL) {
        err = ERR_VAL;
        goto out;
    }

    kv = (struct json_keyval*) *cursor;
    err = tmm_json_cache_parse_object(obj);
    ERR(err, out);

    if (TAILLIST_EMPTY(&obj->kvps)) {
        err = ERR_NOT_FOUND;
        goto out;
    }

    if (kv == NULL) {
        /* Initialize kv to the end to start at the beginning */
        kv = TAILLIST_LAST(&obj->kvps);
    } else if (kv == TAILLIST_LAST(&obj->kvps)) {
        *cursor = NULL;
        err = ERR_NOT_FOUND;
        goto out;
    }

    kv = TAILLIST_NEXT(kv, next);

    *cursor = (void*)kv;
    *val = kv->value;

out:
    return err;
}

err_t
tmm_json_object_set(struct tmm_json_object *obj, const char *key,
        struct tmm_json_value *val)
{
    err_t err = ERR_OK;
    struct tmm_json_value *dummy;
    void *cursor = NULL;

    err = tmm_json_object_get_next(obj, key, &cursor, &dummy);
    ERR(err, out);

    err = tmm_json_object_set_at(obj, cursor, val);

out:
    return err;
}

err_t
tmm_json_object_set_at(struct tmm_json_object *obj, const void *cursor,
        struct tmm_json_value *val)
{
    err_t err = ERR_OK;
    struct json_keyval *kv;

    if (cursor == NULL || obj == NULL || val == NULL) {
        err = ERR_VAL;
        goto out;
    }

    if (tmm_json_value_is_owned(val)) {
        /* Copy operations may be supported in future but need a deep copy */
        err = ERR_NOT_SUPPORTED;
        goto out;
    }

    kv = (struct json_keyval*) cursor;
    tmm_json_object_set_value(&kv->value, val);

out:
    return err;
}

err_t
tmm_json_object_add(struct tmm_json_object *obj, const char *key,
        struct tmm_json_value *val)
{
    err_t err = ERR_OK;
    struct json_keyval *kv;
    UINT32 key_len = 0;

    if (obj == NULL || key == NULL || val == NULL) {
        err = ERR_VAL;
        goto out;
    }

    key_len = strlen(key);
    if (key_len == 0) {
        err = ERR_VAL;
        goto out;
    }

    if (tmm_json_value_is_owned(val)) {
        /* Copy operations may be supported in future but need a deep copy */
        err = ERR_NOT_SUPPORTED;
        goto out;
    }

    err = tmm_json_cache_parse_object(obj);
    ERR(err, out);

    obj->nkvps++;
    err = tmm_json_keyval_create(&kv, key, key_len, val);
    ERR(err, out);
    kv->value->parsed = TRUE;
    kv->value->owner = obj->parent;
    tmm_json_value_set_edited(kv->value);

    TAILLIST_INSERT_TAIL(&obj->kvps, kv, next);

out:
    return err;
}

err_t
tmm_json_object_del(struct tmm_json_object *obj, const char *key)
{
    err_t err = ERR_OK;
    struct tmm_json_value *dummy;
    void *cursor = NULL;

    err = tmm_json_object_get_next(obj, key, &cursor, &dummy);
    ERR(err, out);

    err = tmm_json_object_del_at(obj, &cursor);

out:
    return err;
}

err_t
tmm_json_object_del_at(struct tmm_json_object *obj, void **cursor)
{
    err_t err = ERR_OK;
    struct json_keyval *kv;

    if (cursor == NULL || obj == NULL) {
        err = ERR_VAL;
        goto out;
    }

    kv = (struct json_keyval*) *cursor;
    obj->nkvps--;
    TAILLIST_REMOVE(&obj->kvps, kv, next);
    tmm_json_value_set_edited(kv->value->owner);
    tmm_json_keyval_free(kv);

    *cursor = NULL;

out:
    return err;
}

/******************************************************************************
 * Interface Functions: Operations on a JSON Array.
 * Descriptions are in the header json_parse.h .
 */

struct tmm_json_cache *
tmm_json_array_get_cache(struct tmm_json_array *ary)
{
    struct tmm_json_cache *json;

    if (ary == NULL) {
        json = NULL;
        goto out;
    }
    json = ary->json;

out:
    return json;
}

err_t
tmm_json_array_size(struct tmm_json_array *ary, UINT32 *size)
{
    err_t err = ERR_OK;

    if (size == NULL) {
        err = ERR_VAL;
        goto out;
    }
    if (ary == NULL) {
        *size = 0;
        goto out;
    }
    err = tmm_json_cache_parse_array(ary);
    ERR(err, out);
    *size = ary->nvals;
out:
    return err;
}

err_t
tmm_json_array_get(struct tmm_json_array *ary, const UINT32 idx,
    struct tmm_json_value **val)
{
    err_t err = ERR_OK;

    err = tmm_json_cache_parse_array(ary);
    ERR(err, out);
    if (idx >= ary->nvals) {
        err = ERR_BOUNDS;
        goto out;
    }
    if (val != NULL) {
        *val = (*(ary->vals))[idx];
    }
out:
    return err;
}

err_t
tmm_json_array_set(struct tmm_json_array *ary, UINT32 idx,
    struct tmm_json_value *val)
{
    err_t err = ERR_OK;

    if (val == NULL) {
        err = ERR_VAL;
        goto out;
    }
    if (tmm_json_value_is_owned(val)) {
        /* Copy operations may be supported in future but need a deep copy */
        err = ERR_NOT_SUPPORTED;
        goto out;
    }
    err = tmm_json_cache_parse_array(ary);
    ERR(err, out);
    if (idx >= ary->nvals) {
        err = ERR_BOUNDS;
        goto out;
    }
    tmm_json_value_release((*(ary->vals))[idx]);
    (*(ary->vals))[idx] = val;
    val->owner = ary->parent;
    val->json = ary->json;
    tmm_json_value_set_edited(val);

out:
    return err;
}

err_t
tmm_json_array_insert(struct tmm_json_array *ary, UINT32 idx,
    struct tmm_json_value *val)
{
    unsigned nchunks;
    void *newbuf;
    int i;
    err_t err = ERR_OK;

    /*
     * XXX: This is an inefficient implementation that slides all items
     * when inserting anywhere but the end. Will likely be reworked
     */

    if (val == NULL) {
        err = ERR_VAL;
        goto out;
    }
    if (tmm_json_value_is_owned(val)) {
        /* Copy operations may be supported in future but need a deep copy */
        err = ERR_NOT_SUPPORTED;
        goto out;
    }
    err = tmm_json_cache_parse_array(ary);
    ERR(err, out);
    if (idx > ary->nvals) { /* Can only insert ONE space after the end */
        err = ERR_BOUNDS;
        goto out;
    }

    /* If we are entering a new chunk of memory needed, grow the array */
    nchunks = 1 + (ary->nvals / JSON_ARRAY_CHUNK_SIZE);
    if (nchunks > ary->nchunks) {
        newbuf = urealloc(ary->vals, nchunks *
                    sizeof(struct tmm_json_value*) * JSON_ARRAY_CHUNK_SIZE,
                    M_JSON, 0);
        ERR_MEM(newbuf, err, out);

        ary->vals = newbuf;
        ary->nchunks = nchunks;
    }

    for (i = ary->nvals++; i > idx; i--) {
        /* Slide up any values after the inserted one */
        (*(ary->vals))[i] = (*(ary->vals))[i-1];
    }
    (*(ary->vals))[idx] = val;
    val->owner = ary->parent;
    val->json = ary->json;
    tmm_json_value_set_edited(val);

out:
    return err;
}

err_t
tmm_json_array_del(struct tmm_json_array *ary, UINT32 idx)
{
    int i;
    err_t err = ERR_OK;

    /*
     * XXX: This is an inefficient implementation that slides all items
     * when deleting any except the last item. Will likely be reworked
     */

    err = tmm_json_cache_parse_array(ary);
    ERR(err, out);
    if (idx >= ary->nvals) {
        err = ERR_BOUNDS;
        goto out;
    }

    tmm_json_value_release((*(ary->vals))[idx]);
    ary->nvals--;
    for (i = idx; i < ary->nvals; i++) {
        /* Slide down any values to fill in the place of the deleted one */
        (*(ary->vals))[i] = (*(ary->vals))[i+1];
    }

    tmm_json_value_set_edited(ary->parent);

out:
    return err;
}

err_t
tmm_json_array_find(struct tmm_json_array *ary, struct tmm_json_value *target,
        UINT32 *idx, UINT32 start_idx)
{
    struct tmm_json_value *curval;
    UINT32 curidx;
    BOOL matching;
    err_t ret = ERR_OK;
    err_t err;

    if (ary == NULL || idx == NULL || target == NULL) {
        ret = ERR_VAL;
        goto out;
    }
    ret = tmm_json_cache_parse_array(ary);
    ERR(ret, out);
    if (start_idx >= ary->nvals) {
        ret = ERR_BOUNDS;
        goto out;
    }

    for (curidx = start_idx; curidx < ary->nvals; curidx++) {
        curval = (*(ary->vals))[curidx];
        err = tmm_json_value_equal(curval, target, &matching);
        ERR(err, out);
        if (matching) {
            goto found;
        }
    }
    ret = ERR_NOT_FOUND;
    goto out;

found:
    *idx = curidx;
out:
    return ret;
}

err_t
tmm_json_value_clone(struct tmm_json_value *src,
    struct tmm_json_value **dst, struct tmm_json_cache *dst_cache)
{
    err_t err = ERR_OK;
    INT64 num = 0;
    BOOL b = FALSE;
    struct tmm_json_value *val = NULL;
    struct tmm_json_object *val_obj, *src_obj;
    struct tmm_json_array *val_array, *src_array;
    struct tmm_json_string str;

    DBG_ASSERT ("sane args", (src != NULL) && (dst != NULL) && (dst_cache != NULL));

    err = tmm_json_cache_parse_value(src); /* Hydrate. */
    ERR(err, out);
    err = tmm_json_value_create(&val, dst_cache);
    ERR(err, out);

    switch (src->type) {
    case JSON_TYPE_OBJECT:
        err = tmm_json_value_set_object(val, &val_obj);
        ERR(err, out);
        err = tmm_json_value_get_object(src, &src_obj);
        ERR(err, out);
        err = tmm_json_object_clone(src_obj, val_obj, dst_cache); /* Recurse. */
        break;

    case JSON_TYPE_ARRAY:
        err = tmm_json_value_set_array(val, &val_array);
        ERR(err, out);

        /* Then recursively clone source object's value into it. */
        err = tmm_json_value_get_array(src, &src_array);
        ERR(err, out);
        err = tmm_json_array_clone(src_array, val_array, dst_cache); /* Recurse. */
        break;

    case JSON_TYPE_STRING:
        err = tmm_json_value_get_string(src, &str);
        ERR(err, out);
        err = tmm_json_value_set_string(val, &str);
        break;

    case JSON_TYPE_LITERAL:
        err = tmm_json_value_get_literal(src, &str);
        ERR(err, out);
        err = tmm_json_value_set_literal(val, &str);
        break;

    case JSON_TYPE_INTEGER:
        tmm_json_value_get_integer(src, &num);
        err = tmm_json_value_set_integer(val, num);
        break;

    case JSON_TYPE_BOOL:
        tmm_json_value_get_bool(src, &b);
        err = tmm_json_value_set_bool(val, b);
        break;

    case JSON_TYPE_NULL:
        err = tmm_json_value_set_null(val);
        break;

    default:
        err = ERR_NOT_SUPPORTED;
    }
out:
    if (err == ERR_OK) {
        *dst = val;
    } else {
        /* Cleanup unused allocated value. */
        if (val != NULL) {
            tmm_json_value_free(val);
        }
    }
    return err;
}

err_t
tmm_json_array_clone(struct tmm_json_array *src,
    struct tmm_json_array *dst, struct tmm_json_cache *dst_cache)
{
    UINT32 i, src_len;
    err_t err = ERR_OK;

    DBG_ASSERT ("sane args", (src != NULL) && (dst != NULL) && (dst_cache != NULL));

    err = tmm_json_array_size(src, &src_len);
    ERR(err, out);

    for (i = 0; i < src_len; i++) {
        struct tmm_json_value *src_val;
        struct tmm_json_value *val;

        err = tmm_json_array_get(src, i, &src_val);
        ERR(err, out);

        err = tmm_json_value_clone(src_val, &val, dst_cache);
        ERR(err, out);

        err = tmm_json_array_insert(dst, i, val);
        ERR(err, out);
    }

    tmm_json_array_size(dst, &i);
    DBG_ASSERT("populations match", i == src->nvals);
out:
    return err;
}

err_t
tmm_json_object_clone(struct tmm_json_object *src,
    struct tmm_json_object *dst, struct tmm_json_cache *dst_cache)
{
    void *cursor;
    char *key = NULL;
    UINT32 key_len, expected_keys, actual_keys, dst_keys;
    err_t err = ERR_OK;

    DBG_ASSERT ("sane args", (src != NULL) && (dst != NULL) && (dst_cache != NULL));

    err = tmm_json_object_size(src, &expected_keys);
    DBG_ASSERT("got num keys",err == ERR_OK);
    ERR(err, out);
    actual_keys = 0;

    /* Iterate over all keys in the source object. */
    cursor = NULL;
    for (err = tmm_json_object_get_next_key(src, &cursor, &key, &key_len);
            err != ERR_NOT_FOUND;
            err = tmm_json_object_get_next_key(src, &cursor, &key, &key_len)) {
        struct tmm_json_value *src_val;
        struct tmm_json_value *val;

        actual_keys++;
        err = tmm_json_object_get(src, key, &src_val);
        ERR(err, out);

        err = tmm_json_value_clone(src_val, &val, dst_cache);
        ERR(err, out);

        /* add to destination object */
        err = tmm_json_object_add(dst, key, val);
        ERR(err, out);
    }
    if (err == ERR_NOT_FOUND) { /* Normal termination of loop. */
        err = ERR_OK;
    }

out:
    DBG_ASSERT("key match", expected_keys == actual_keys);
    tmm_json_object_size(dst, &dst_keys);
    DBG_ASSERT("populations match", dst_keys == actual_keys);
    return err;
}

