/* Enable JXMN sibling links between same-level tokens */
#define JXMN_SIBLING_LINKS

/* Enable JXMN strict mode to disable pseudo-json parsing */
#define JXMN_STRICT

/**
 * JSON type identifier. Basic types are:
 *      o Object
 *      o Array
 *      o String
 *      o Other primitive: number, boolean (true/false) or null
 */
typedef enum {
        JXMN_UNDEFINED = 0,
        JXMN_OBJECT = 1,
        JXMN_ARRAY = 2,
        JXMN_STRING = 3,
        JXMN_PRIMITIVE = 4
} jxmntype_t;

enum jxmnerr {
        /* Not enough tokens were provided */
        JXMN_ERROR_NOMEM = -1,
        /* Invalid character inside JSON string */
        JXMN_ERROR_INVAL = -2,
        /* The string is not a full JSON packet, more bytes expected */
        JXMN_ERROR_PART = -3,
        /* There was an error while retriving data from the xbuf */
        JXMN_ERROR_XBUF = -4,
        /* A root element for the tree is complete, but more payload existed and was ignored */
        JXMN_ERROR_EXTRA = -5
};

/**
 * JSON token description.
 * type         type (object, array, string etc.)
 * start        start position in JSON data string
 * end          end position in JSON data string
 */
typedef struct {
        jxmntype_t type;
        int start;
        int end;
        int size;
#ifdef JXMN_SIBLING_LINKS
        int sibling; /* tokidx of the next sibling value. -1 if last val */
#endif
#ifdef JXMN_PARENT_LINKS
        int parent;
#endif
} jxmntok_t;

/**
 * JSON parser. Contains an array of token blocks available. Also stores
 * the string being parsed now and current position in that string
 */
typedef struct {
        unsigned int pos; /* offset in the JSON string */
        unsigned int toknext; /* next token to allocate */
        int toksuper; /* superior token node, e.g parent object or array */
#ifdef JXMN_SIBLING_LINKS
        int tokprev; /* Most recently finished token (end ptr set) */
#endif
} jxmn_parser;

/**
 * F5-specific location state for navigating (discontiguous) xbufs efficiently.
 */
struct jxmn_xbuf_loc {
    xcursor_t   xc;         /* Cursor at last position accessed. */
    int         pos;        /* Last position relative to beginning of xbuf. */
};

/**
 * Create JSON parser over an array of tokens
 */
void jxmn_init(jxmn_parser *parser);

/**
 * Run JSON parser. It parses a JSON data string into and array of tokens, each describing
 * a single JSON object. Receives an xbuf and xcursor that may be reused across many calls.
 *
 * F5 Modification - This function adapted to use xbufs rather than byte strings.
 * Also added eof parameter. When TRUE, signals that the data in the xbuf 'js'
 * is the full and complete JSON payload to parse. When FALSE, signals that
 * additional data may yet be added to the JSON payload and parsed later.
 */

int jxmn_parse(jxmn_parser *parser, struct xbuf *js, struct jxmn_xbuf_loc *loc,
                jxmntok_t *tokens, unsigned int num_tokens, bool eof);

#ifdef __cplusplus
}
