#include <local/sys/types.h>
#include <local/sys/def.h>
#include <local/sys/cpu.h>
#include <local/sys/xbuf.h>

#include "jxmn.h"

/**
 * Allocates a fresh unused token from the token pool.
 */
static jxmntok_t *jxmn_alloc_token(jxmn_parser *parser,
                jxmntok_t *tokens, SIZE num_tokens) {
        jxmntok_t *tok;
        if (parser->toknext >= num_tokens) {
                return NULL;
        }
        tok = &tokens[parser->toknext++];tok->start = tok->end = -1;
        tok->size = 0;
#ifdef JXMN_SIBLING_LINKS
        tok->sibling = -1; /* Assume no next-sibling unless one gets set */
#endif
#ifdef JXMN_PARENT_LINKS
        tok->parent = -1;
#endif
        return tok;
}

/**
 * Get the char at an offset (pos) relative to the beginning of an xbuf.
 * Provide an xcursor to optimize successive lookups during jxmn_parse() tokenization.
 */
static int jxmn_char_at(struct xbuf *xb, struct jxmn_xbuf_loc *loc, int pos, char *data) {
    err_t err;
    char *ptr;

    err = xbuf_move(xb, &loc->xc, pos - loc->pos);
    if (err != ERR_OK)
        return JXMN_ERROR_XBUF;
    loc->pos = pos;
    ptr = xbuf_getptr(xb, loc->xc, NULL);
    *data = *ptr;
    return 0;
}

/**
 * Fills token type and boundaries.
 */
static void jxmn_fill_token(jxmntok_t *token, jxmntype_t type,
                            int start, int end) {
        token->type = type;
        token->start = start;
        token->end = end;
        token->size = 0;
}

/**
 * Fills next available token with JSON primitive.
 */
static int jxmn_parse_primitive(jxmn_parser *parser, struct xbuf *js, struct jxmn_xbuf_loc *loc,
                jxmntok_t *tokens, SIZE num_tokens, bool eof) {
        jxmntok_t *token;
        int start;
        int r;
        char c;

        start = parser->pos;

        for (; parser->pos < js->len; parser->pos++) {
                r = jxmn_char_at(js, loc, parser->pos, &c);
                if (r < 0) return r;
                if (c == '\0') {
                        break;
                }
                switch (c) {
#ifndef JXMN_STRICT
                        /* In strict mode primitive must be followed by "," or "}" or "]" */
                        case ':':
#endif
                        case '\t' : case '\r' : case '\n' : case ' ' :
                        case ','  : case ']'  : case '}' :
                                goto found;
                }
                if (c < 32 || c >= 127) {
                        parser->pos = start;
                        return JXMN_ERROR_INVAL;
                }
        }

        /*
         * F5 MODIFICATION - previously the 'if (!eof)' was absent, and
         * this whole block was surrounded by JXMN_STRICT. However, we
         * want to allow a primitive without a syntactical end to be parsed
         * as a full complete value if it is terminated by the end of the
         * payload (fall through to alloc token). This JXMN_ERROR_PART is
         * necessary with or without JXMN_STRICT so as to not confuse the
         * tokenizer when it re-enters in the middle of a primitive, hence
         * the removal of the JXMN_STRICT check.
         */
        if (!eof) {
                parser->pos = start;
                return JXMN_ERROR_PART;
        }

found:
        if (tokens == NULL) {
                parser->pos--;
                return 0;
        }
        token = jxmn_alloc_token(parser, tokens, num_tokens);
        if (token == NULL) {
                parser->pos = start;
                return JXMN_ERROR_NOMEM;
        }
        jxmn_fill_token(token, JXMN_PRIMITIVE, start, parser->pos);
#ifdef JXMN_SIBLING_LINKS
        /* (parser->toknext - 1) is our new token's index */
        if (parser->tokprev != -1 && parser->tokprev != parser->toknext - 1) {
                tokens[parser->tokprev].sibling = parser->toknext - 1;
        }
        parser->tokprev = parser->toknext - 1;
#endif
#ifdef JXMN_PARENT_LINKS
        token->parent = parser->toksuper;
#endif
        parser->pos--;
        return 0;
}

/**
 * Fills next token with JSON string.
 */
static int jxmn_parse_string(jxmn_parser *parser, struct xbuf *js, struct jxmn_xbuf_loc *loc,
                jxmntok_t *tokens, SIZE num_tokens) {
        jxmntok_t *token;

        int start = parser->pos;
        int r;

        parser->pos++;

        /* Skip starting quote */
        for (; parser->pos < js->len; parser->pos++) {
                char c;
                r = jxmn_char_at(js, loc, parser->pos, &c);
                if (r < 0) return r;
                if (c == '\0') break;

                /* Quote: end of string */
                if (c == '\"') {
                        if (tokens == NULL) {
                                return 0;
                        }
                        token = jxmn_alloc_token(parser, tokens, num_tokens);
                        if (token == NULL) {
                                parser->pos = start;
                                return JXMN_ERROR_NOMEM;
                        }
                        jxmn_fill_token(token, JXMN_STRING, start+1, parser->pos);
#ifdef JXMN_SIBLING_LINKS
                        /* (parser->toknext - 1) is our new token's index */
                        if (parser->tokprev != -1) {
                                tokens[parser->tokprev].sibling = parser->toknext - 1;
                        }
                        parser->tokprev = parser->toknext - 1;
#endif
#ifdef JXMN_PARENT_LINKS
                        token->parent = parser->toksuper;
#endif
                        return 0;
                }

                /* Backslash: Quoted symbol expected */
                if (c == '\\' && parser->pos + 1 < js->len) {
                        int i;
                        char escp;
                        r = jxmn_char_at(js, loc, ++parser->pos, &escp);
                        if (r < 0) return r;
                        switch (escp) {
                                /* Allowed escaped symbols */
                                case '\"': case '/' : case '\\' : case 'b' :
                                case 'f' : case 'r' : case 'n'  : case 't' :
                                        break;
                                /* Allows escaped symbol \uXXXX */
                                case 'u':
                                        parser->pos++;
                                        for(i = 0; i < 4 && parser->pos < js->len; i++) {
                                                char hexchr;
                                                r = jxmn_char_at(js, loc, parser->pos, &hexchr);
                                                if (r < 0) return r;
                                                if (c == '\0') break;

                                                /* If it isn't a hex character we have an error */
                                                if(!((hexchr >= 48 && hexchr <= 57) || /* 0-9 */
                                                                        (hexchr >= 65 && hexchr <= 70) || /* A-F */
                                                                        (hexchr >= 97 && hexchr <= 102))) { /* a-f */
                                                        parser->pos = start;
                                                        return JXMN_ERROR_INVAL;
                                                }
                                                parser->pos++;
                                        }
                                        parser->pos--;
                                        break;
                                /* Unexpected symbol */
                                default:
                                        parser->pos = start;
                                        return JXMN_ERROR_INVAL;
                        }
                }
        }
        parser->pos = start;
        return JXMN_ERROR_PART;
}

/**
 * Parse JSON string and fill tokens.
 */
int jxmn_parse(jxmn_parser *parser, struct xbuf *js, struct jxmn_xbuf_loc *loc,
                jxmntok_t *tokens, unsigned int num_tokens, bool eof) {
        int r;
        int i;
        jxmntok_t *token;
        int count = parser->toknext;

        for (; parser->pos < js->len; parser->pos++) {
                char c;
                jxmntype_t type;

                r = jxmn_char_at(js, loc, parser->pos, &c);
                if (r < 0) return r;
                if (c == '\0') {
                        break;
                }

                switch (c) {
                        case '{': case '[':
                                if (count > 0 && parser->toksuper == -1 && tokens != NULL) {
                                        /* Already had a root element */
                                        return JXMN_ERROR_EXTRA;
                                }
                                count++;
                                if (tokens == NULL) {
                                        break;
                                }
                                token = jxmn_alloc_token(parser, tokens, num_tokens);
                                if (token == NULL)
                                        return JXMN_ERROR_NOMEM;
#ifdef JXMN_SIBLING_LINKS
                                if (parser->tokprev != -1) {
                                        tokens[parser->tokprev].sibling = parser->toknext - 1;
                                        parser->tokprev = -1;
                                }
#endif
                                if (parser->toksuper != -1) {
                                        tokens[parser->toksuper].size++;
#ifdef JXMN_PARENT_LINKS
                                        token->parent = parser->toksuper;
#endif
                                }
                                token->type = (c == '{' ? JXMN_OBJECT : JXMN_ARRAY);
                                token->start = parser->pos;
                                parser->toksuper = parser->toknext - 1;
                                break;
                        case '}': case ']':
                                if (tokens == NULL)
                                        break;
                                type = (c == '}' ? JXMN_OBJECT : JXMN_ARRAY);
#ifdef JXMN_PARENT_LINKS
                                if (parser->toknext < 1) {
                                        return JXMN_ERROR_INVAL;
                                }
                                token = &tokens[parser->toknext - 1];
                                for (;;) {
                                        if (token->start != -1 && token->end == -1) {
                                                if (token->type != type) {
                                                        return JXMN_ERROR_INVAL;
                                                }
                                                token->end = parser->pos + 1;
#ifdef JXMN_SIBLING_LINKS
                                                /* Get idx of token in tokens */
                                                parser->tokprev = token - tokens;
#endif
                                                parser->toksuper = token->parent;
                                                break;
                                        }
                                        if (token->parent == -1) {
                                                if(token->type != type || parser->toksuper == -1) {
                                                        return JXMN_ERROR_INVAL;
                                                }
                                                break;
                                        }
                                        token = &tokens[token->parent];
                                }
#else
                                for (i = parser->toknext - 1; i >= 0; i--) {
                                        token = &tokens[i];
                                        if (token->start != -1 && token->end == -1) {
                                                if (token->type != type) {
                                                        return JXMN_ERROR_INVAL;
                                                }
                                                parser->toksuper = -1;
                                                token->end = parser->pos + 1;
#ifdef JXMN_SIBLING_LINKS
                                                parser->tokprev = i;
#endif
                                                break;
                                        }
                                }
                                /* Error if unmatched closing bracket */
                                if (i == -1) return JXMN_ERROR_INVAL;
                                for (; i >= 0; i--) {
                                        token = &tokens[i];
                                        if (token->start != -1 && token->end == -1) {
                                                parser->toksuper = i;
                                                break;
                                        }
                                }
#endif
                                break;
                        case '\"':
                                if (count > 0 && parser->toksuper == -1 && tokens != NULL) {
                                        /* Already had a root element */
                                        return JXMN_ERROR_EXTRA;
                                }
                                r = jxmn_parse_string(parser, js, loc, tokens, num_tokens);
                                if (r < 0) return r;
                                count++;
                                if (parser->toksuper != -1 && tokens != NULL)
                                        tokens[parser->toksuper].size++;
                                break;
                        case '\t' : case '\r' : case '\n' : case ' ':
                                break;
                        case ':':
                                if ((parser->toksuper == -1 || tokens[parser->toksuper].type != JXMN_OBJECT)
                                                && tokens != NULL) {
                                        /* Not inside an object */
                                        return JXMN_ERROR_INVAL;
                                }
                                parser->toksuper = parser->toknext - 1;
                                break;
                        case ',':
                                if (tokens != NULL && parser->toksuper != -1 &&
                                                tokens[parser->toksuper].type != JXMN_ARRAY &&
                                                tokens[parser->toksuper].type != JXMN_OBJECT) {
#ifdef JXMN_PARENT_LINKS
                                        parser->toksuper = tokens[parser->toksuper].parent;
#else
                                        for (i = parser->toknext - 1; i >= 0; i--) {
                                                if (tokens[i].type == JXMN_ARRAY || tokens[i].type == JXMN_OBJECT) {
                                                        if (tokens[i].start != -1 && tokens[i].end == -1) {
                                                                parser->toksuper = i;
                                                                break;
                                                        }
                                                }
                                        }
#endif
                                }
                                break;
#ifdef JXMN_STRICT
                        /* In strict mode primitives are: numbers and booleans */
                        case '-': case '0': case '1' : case '2': case '3' : case '4':
                        case '5': case '6': case '7' : case '8': case '9':
                        case 't': case 'f': case 'n' :
                                if (tokens != NULL) {
                                        if (parser->toksuper == -1) {
                                                if (count > 0) {
                                                        /* Already had a root element */
                                                        return JXMN_ERROR_EXTRA;
                                                }
                                        } else {
                                                /* And they must not be keys of the object */
                                                jxmntok_t *t = &tokens[parser->toksuper];
                                                if (t->type == JXMN_OBJECT ||
                                                                (t->type == JXMN_STRING && t->size != 0)) {
                                                        return JXMN_ERROR_INVAL;
                                                }
                                        }
                                }
#else
                        /* In non-strict mode every unquoted value is a primitive */
                        default:
#endif
                                r = jxmn_parse_primitive(parser, js, loc, tokens, num_tokens, eof);
                                if (r < 0) return r;
                                count++;
                                if (parser->toksuper != -1 && tokens != NULL)
                                        tokens[parser->toksuper].size++;
                                break;

#ifdef JXMN_STRICT
                        /* Unexpected char in strict mode */
                        default:
                                if (count > 0 && parser->toksuper == -1 && tokens != NULL) {
                                        /* Already had a root element */
                                        return JXMN_ERROR_EXTRA;
                                }
                                return JXMN_ERROR_INVAL;
#endif
                }
        }

        if (tokens != NULL) {
                for (i = parser->toknext - 1; i >= 0; i--) {
                        /* Unmatched opened object or array */
                        if (tokens[i].start != -1 && tokens[i].end == -1) {
                                return JXMN_ERROR_PART;
                        }
                }
        }

        return count;
}

/**
 * Creates a new parser based over a given  buffer with an array of tokens
 * available.
 */
void jxmn_init(jxmn_parser *parser) {
        parser->pos = 0;
        parser->toknext = 0;
        parser->toksuper = -1;
#ifdef JXMN_SIBLING_LINKS
        parser->tokprev = -1;
#endif
}

